class CartFragment : Fragment(R.layout.fragment_cart) {   // container
    private val vm: CartViewModel by viewModels()
    override fun onViewCreated(view: View, b: Bundle?) {
        val lines = view.findViewById<RecyclerView>(R.id.lines)   // passive child view
        vm.uiState.onEach { lines.adapter = CartAdapter(it.lines) }
            .launchIn(viewLifecycleOwner.lifecycleScope)
    }
}
